import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { Router, provideRouter } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { BookingService } from '../core/booking.service';
import { inProgressBookingGuard } from '../core/guards';
import { Checkout } from './checkout';

describe('Checkout', () => {
  beforeEach(() => sessionStorage.clear());

  async function open() {
    TestBed.configureTestingModule({
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        provideRouter([
          { path: '', component: Checkout },
          {
            path: 'screenings/:id/checkout',
            canActivate: [inProgressBookingGuard],
            component: Checkout,
          },
          { path: 'confirmation', component: Checkout },
        ]),
        provideNativeDateAdapter(),
      ],
    });
    const booking = TestBed.inject(BookingService);
    booking.start(1);
    booking.setItems(['R15C1', 'R7C12', 'R15C3']);
    const harness = await RouterTestingHarness.create();
    await harness.navigateByUrl('/screenings/1/checkout');
    const el: HTMLElement = harness.fixture.nativeElement;
    const q = (id: string) => el.querySelector<HTMLElement>(`[data-testid="${id}"]`);
    const type = (id: string, value: string) => {
      const input = q(id) as HTMLInputElement;
      input.value = value;
      input.dispatchEvent(new Event('input'));
      harness.detectChanges();
    };
    return { harness, q, type, booking, http: TestBed.inject(HttpTestingController) };
  }

  it('redirects without a matching booking', async () => {
    TestBed.configureTestingModule({
      providers: [provideRouter([{ path: 'screenings/:id/checkout', canActivate: [inProgressBookingGuard], component: Checkout }, { path: '', component: Checkout }])],
    });
    const harness = await RouterTestingHarness.create();
    await harness.navigateByUrl('/screenings/1/checkout');
    expect(TestBed.inject(Router).url).toBe('/');
  });

  it('shows messages after blur, keeps values and pays', async () => {
    const { harness, q, type, booking, http } = await open();
    expect(q('pay-button')!.textContent!.trim()).toBe('Pay 210.00 PLN');
    expect(q('first-name-error')).toBeNull();

    q('first-name-input')!.dispatchEvent(new Event('blur'));
    harness.detectChanges();
    expect(q('first-name-error')!.textContent).toBe('First name is required');
    type('first-name-input', 'A');
    expect(q('first-name-error')!.textContent).toBe('First name must be at least 2 characters');

    (q('pay-button') as HTMLButtonElement).click();
    harness.detectChanges();
    expect(q('confirm-email-error')!.textContent).toBe('Confirm email is required');
    expect(q('terms-error')!.textContent).toBe('You must accept the terms and conditions');
    const toasts = document.querySelectorAll('[data-testid="toast"]');
    expect(toasts.length).toBe(1);
    expect(toasts[0].textContent).toContain('The form contains errors');
    http.expectNone('http://localhost:3000/reservations');

    type('first-name-input', 'Anna');
    type('last-name-input', 'Kowalska');
    type('email-input', 'anna@example.com');
    type('confirm-email-input', 'anna@example.com');
    type('phone-input', '123456789');
    (q('terms-checkbox')!.querySelector('input') as HTMLInputElement).click();
    harness.detectChanges();
    expect(booking.booking()?.form.firstName).toBe('Anna');
    expect(booking.booking()?.form.terms).toBe(true);

    (q('pay-button') as HTMLButtonElement).click();
    harness.detectChanges();
    expect((q('pay-button') as HTMLButtonElement).disabled).toBe(true);
    expect(q('pay-button')!.textContent!.trim()).toBe('Processing…');
    const req = http.expectOne('http://localhost:3000/reservations');
    expect(req.request.body).toEqual({
      screeningId: 1,
      seats: ['R7C12', 'R15C1', 'R15C2', 'R15C3', 'R15C4'],
      customer: { firstName: 'Anna', lastName: 'Kowalska', email: 'anna@example.com', phone: '123456789' },
      totalPrice: 210,
    });
    req.flush('x', { status: 500, statusText: 'err' });
    harness.detectChanges();
    expect((q('pay-button') as HTMLButtonElement).disabled).toBe(false);
    expect(booking.booking()?.paid).toBe(false);

    (q('pay-button') as HTMLButtonElement).click();
    http.expectOne('http://localhost:3000/reservations').flush({ id: 1 });
    await harness.fixture.whenStable();
    expect(booking.booking()?.paid).toBe(true);
    expect(booking.booking()?.email).toBe('anna@example.com');
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { MovieList } from './movie-list';

const movies = [
  { id: 1, title: 'A', genre: 'Drama', runtimeMinutes: 128, format: 'PL dubbing' },
  { id: 2, title: 'B', genre: 'Sci-Fi', runtimeMinutes: 90, format: 'PL subtitles' },
];
const screening = (id: number, movieId: number, date: string, time: string) => ({
  id,
  movieId,
  date,
  time,
  occupiedSeats: [],
});

describe('MovieList', () => {
  beforeEach(() => vi.useFakeTimers({ toFake: ['Date'], now: new Date(2026, 8, 15, 10, 0) }));
  afterEach(() => vi.useRealTimers());

  async function open(url: string) {
    TestBed.configureTestingModule({
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        provideRouter([{ path: '', component: MovieList }]),
        provideNativeDateAdapter(),
      ],
    });
    const http = TestBed.inject(HttpTestingController);
    const harness = await RouterTestingHarness.create();
    await harness.navigateByUrl(url);
    const el: HTMLElement = harness.fixture.nativeElement;
    const q = (id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));
    return { http, harness, q };
  }

  it('shows loading, then the selected day', async () => {
    const { http, harness, q } = await open('/');
    harness.detectChanges();
    expect(q('movies-loading').length).toBe(1);
    expect(q('movie-card').length).toBe(0);

    http.expectOne('http://localhost:3000/movies').flush(movies);
    http.expectOne('http://localhost:3000/screenings').flush([
      screening(1, 1, '2026-09-15', '18:00'),
      screening(2, 1, '2026-09-15', '16:00'),
      screening(3, 2, '2026-09-16', '12:00'),
    ]);
    harness.detectChanges();

    expect(q('movies-loading').length).toBe(0);
    expect(q('day-button').map((b) => b.textContent!.trim())).toEqual([
      'Today',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
    ]);
    expect(q('day-button')[0].dataset['selected']).toBe('true');
    expect(q('day-button')[1].dataset['selected']).toBe('false');
    expect(q('movie-card').length).toBe(1);
    expect(q('movie-runtime')[0].textContent).toBe('128 min');
    expect(q('screening-button').map((b) => b.textContent!.trim())).toEqual(['16:00', '18:00']);
    expect(q('screening-button')[0].dataset['screeningId']).toBe('2');

    q('day-button')[1].click();
    await harness.fixture.whenStable();
    harness.detectChanges();
    expect(q('movie-title')[0].textContent).toBe('B');
    expect(q('day-button')[1].dataset['selected']).toBe('true');
  });

  it('shows the empty state for a date from the URL and ignores past dates', async () => {
    const { http, harness, q } = await open('/?date=2026-10-01');
    http.expectOne('http://localhost:3000/movies').flush(movies);
    http.expectOne('http://localhost:3000/screenings').flush([screening(1, 1, '2026-09-15', '18:00')]);
    harness.detectChanges();
    expect(q('movies-empty').length).toBe(1);
    expect(q('movie-card').length).toBe(0);
    expect(q('day-button').every((b) => b.dataset['selected'] === 'false')).toBe(true);

    await harness.navigateByUrl('/?date=2026-09-01');
    harness.detectChanges();
    expect(q('day-button')[0].dataset['selected']).toBe('true');
  });

  it('shows an error with a working retry', async () => {
    const { http, harness, q } = await open('/');
    http.expectOne('http://localhost:3000/movies').flush('x', { status: 500, statusText: 'err' });
    http.match('http://localhost:3000/screenings');
    harness.detectChanges();
    expect(q('movies-error')[0].textContent).toBe('Failed to load movies');
    q('movies-retry-button')[0].click();
    harness.detectChanges();
    expect(q('movies-loading').length).toBe(1);
    http.expectOne('http://localhost:3000/movies').flush(movies);
    http.expectOne('http://localhost:3000/screenings').flush([]);
    harness.detectChanges();
    expect(q('movies-empty').length).toBe(1);
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { BookingService } from '../core/booking.service';
import { SeatMap } from './seat-map';

describe('SeatMap', () => {
  beforeEach(() => sessionStorage.clear());

  async function open() {
    TestBed.configureTestingModule({
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        provideRouter([{ path: 'screenings/:id/seats', component: SeatMap }]),
        provideNativeDateAdapter(),
      ],
    });
    const http = TestBed.inject(HttpTestingController);
    const harness = await RouterTestingHarness.create();
    await harness.navigateByUrl('/screenings/1/seats');
    http.expectOne('http://localhost:3000/screenings/1').flush({
      id: 1,
      movieId: 1,
      date: '2026-09-15',
      time: '16:00',
      occupiedSeats: ['R3C7', 'R15C5', 'R15C6'],
    });
    http.expectOne('http://localhost:3000/movies/1').flush({
      id: 1,
      title: 'X',
      genre: 'Y',
      runtimeMinutes: 1,
      format: 'PL dubbing',
    });
    harness.detectChanges();
    const el: HTMLElement = harness.fixture.nativeElement;
    const q = (id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));
    const seat = (row: number, col: number) =>
      q('seat').find((s) => s.dataset['row'] === `${row}` && s.dataset['column'] === `${col}`)!;
    const couch = (start: number) => q('couch').find((c) => c.dataset['columnStart'] === `${start}`)!;
    const count = () => Number(q('selected-seats-count')[0].textContent!.replace(/\D/g, ''));
    return { harness, q, seat, couch, count };
  }

  it('draws the auditorium', async () => {
    const { q, seat, couch } = await open();
    expect(q('seat-row').length).toBe(15);
    expect(q('seat').length).toBe(296);
    expect(q('couch').length).toBe(12);
    expect(q('aisle').length).toBe(30);
    expect(q('row-label-left').length).toBe(15);
    expect(q('row-label-right').length).toBe(15);
    expect(q('seat').filter((s) => s.dataset['state'] === 'accessible').length).toBe(6);
    expect(q('seat-map-subtitle')[0].textContent).toBe('Show Date: Tuesday 15 Sep 16:00');
    expect(seat(3, 7).dataset['state']).toBe('unavailable');
    expect(couch(5).dataset['state']).toBe('unavailable');
    expect(seat(1, 1)).toBeUndefined();
    expect(seat(11, 1)).toBeDefined();
  });

  it('selects, deselects and caps at 10 seats', async () => {
    const { harness, q, seat, couch, count } = await open();
    seat(7, 12).click();
    seat(7, 11).click();
    couch(1).click();
    harness.detectChanges();
    expect(count()).toBe(4);
    expect(q('selected-seats-row').map((r) => r.textContent)).toEqual([
      'Row 7: 11, 12',
      'Row 15: 1-2',
    ]);

    seat(3, 7).click();
    couch(5).click();
    harness.detectChanges();
    expect(count()).toBe(4);

    for (let col = 5; col <= 10; col++) seat(8, col).click();
    harness.detectChanges();
    expect(count()).toBe(10);
    couch(3).click();
    seat(9, 5).click();
    harness.detectChanges();
    expect(count()).toBe(10);
    expect(seat(9, 5).dataset['state']).toBe('available');

    couch(1).click();
    harness.detectChanges();
    expect(count()).toBe(8);
    expect(TestBed.inject(BookingService).booking()?.items).toContain('R7C12');
  });
});
